<script type="application/ld+json">
{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    { "@type": "Question", "name": "ما هي خدمات ناري ستور بالضبط؟", "acceptedAnswer": { "@type": "Answer", "text": "نوفّر ثلاث مجموعات: شحن الألعاب (جواهر فري فاير، شدات ببجي UC، نقاط كول أوف ديوتي CP، كوينز تيك توك)، والبطاقات والاشتراكات (آيتونز، جوجل بلاي، شاهد VIP، نتفليكس)، وخدمات نمو السوشيال ميديا (متابعين ولايكات انستقرام، متابعين تيك توك، مشاهدات يوتيوب) — بإجمالي 12 خدمة و49 فئة سعرية." } },
    { "@type": "Question", "name": "كيف أدفع؟ وهل هناك طرق دفع غير شام كاش؟", "acceptedAnswer": { "@type": "Answer", "text": "الدفع حالياً عبر شام كاش فقط، لأنه الأسرع والأكثر انتشاراً داخل سوريا. نرسل لك تفاصيل التحويل على واتساب، وترسل لنا صورة الإيصال، ثم نبدأ التنفيذ مباشرة." } },
    { "@type": "Question", "name": "كم يستغرق تنفيذ الطلب؟", "acceptedAnswer": { "@type": "Answer", "text": "شحن الألعاب والبطاقات غالباً خلال دقائق من تأكيد الدفع. الاشتراكات تحتاج وقتاً قصيراً إضافياً حسب توفر الحسابات. باقات نمو السوشيال ميديا تبدأ بالتسليم التدريجي خلال وقت قصير وتكتمل حسب حجم الباقة." } },
    { "@type": "Question", "name": "هل تطلبون كلمة مرور حسابي؟", "acceptedAnswer": { "@type": "Answer", "text": "لا، إطلاقاً. شحن الألعاب يتم عبر معرّف اللاعب (ID) فقط، وخدمات النمو عبر اسم المستخدم العام أو رابط المنشور. أي جهة تطلب كلمة مرورك باسمنا لا تمثّلنا." } },
    { "@type": "Question", "name": "هل الأسعار المعروضة نهائية؟", "acceptedAnswer": { "@type": "Answer", "text": "الأسعار المعروضة استرشادية وتتغيّر مع سعر الصرف. نؤكد لك السعر النهائي على واتساب قبل أي تحويل، فلا توجد مفاجآت بعد الدفع." } },
    { "@type": "Question", "name": "ماذا لو حدث خطأ في الطلب؟", "acceptedAnswer": { "@type": "Answer", "text": "إن كان الخطأ من طرفنا (فئة خاطئة، خدمة غير مكتملة، كود غير صالح) نصحّح الطلب فوراً أو نعيد المبلغ الخاص بالجزء غير المنفَّذ، حسب سياسة الاسترجاع المنشورة." } },
    { "@type": "Question", "name": "هل يمكنني الطلب من خارج سوريا؟", "acceptedAnswer": { "@type": "Answer", "text": "نعم، طالما يمكنك الدفع عبر شام كاش. راسلنا على واتساب وسنوضح لك الخيارات المتاحة لحالتك." } },
    { "@type": "Question", "name": "هل خدمات زيادة المتابعين آمنة على حسابي؟", "acceptedAnswer": { "@type": "Answer", "text": "نعتمد تسليماً تدريجياً يحاكي النمو الطبيعي، ولا نطلب أي بيانات دخول. مع ذلك، ننصح دائماً بإبقاء الحساب عاماً أثناء التنفيذ لضمان أفضل نتيجة." } },
    { "@type": "Question", "name": "هل يمكنني إلغاء الطلب بعد الدفع؟", "acceptedAnswer": { "@type": "Answer", "text": "قبل بدء التنفيذ يمكننا النظر في طلب الإلغاء حسب حالة العملية. بعد التنفيذ الناجح لا يمكن الاسترجاع لأن الخدمات الرقمية تُسلَّم فوراً — التفاصيل في صفحة سياسة الاسترجاع." } },
    { "@type": "Question", "name": "هل تقدّمون خصومات للطلبات الكبيرة؟", "acceptedAnswer": { "@type": "Answer", "text": "نعم، الفئات الكبيرة تحمل أصلاً سعراً أفضل لكل وحدة، ويمكن التفاوض على الطلبات المتكررة أو الكميات الكبيرة عبر واتساب." } },
    { "@type": "Question", "name": "هل أحتاج إنشاء حساب في الموقع؟", "acceptedAnswer": { "@type": "Answer", "text": "لا. لا يوجد تسجيل ولا حسابات — تختار الفئة وتراسلنا على واتساب مباشرة، وهذا يجعل العملية أسرع ويقلل البيانات التي نجمعها عنك." } },
    { "@type": "Question", "name": "كيف أتأكد أنكم لستم محتالين؟", "acceptedAnswer": { "@type": "Answer", "text": "نعرض أسعارنا علناً، ونؤكد كل التفاصيل قبل الدفع، وننشر سياسات واضحة للخصوصية والاسترجاع، ولا نطلب كلمة مرور أي حساب. يمكنك أيضاً البدء بطلب صغير لتجربة الخدمة قبل طلب فئة كبيرة." } },
    { "@type": "Question", "name": "هل الأسعار تشمل أي رسوم إضافية؟", "acceptedAnswer": { "@type": "Answer", "text": "السعر الذي نؤكده لك على واتساب هو المبلغ النهائي المطلوب تحويله. لا نضيف أي رسوم بعد ذلك." } },
    { "@type": "Question", "name": "ماذا لو تأخر تنفيذ طلبي؟", "acceptedAnswer": { "@type": "Answer", "text": "راسلنا في نفس المحادثة وسنخبرك بحالة الطلب بدقة. التأخير غالباً يكون بسبب ضغط الطلبات أو مشكلة مؤقتة من مزود الخدمة، ونبقيك على اطلاع حتى الاكتمال." } }
  ]
}
