    'content_html' => '<section class="hero" style="padding-bottom:30px;">
  <div class="wrap">
    <p class="eyebrow">مركز المساعدة</p>
    <h1>الأسئلة <em>الشائعة</em></h1>
    <p class="lead">جمعنا هنا كل ما يسألنا عنه العملاء عادة. إن لم تجد إجابتك، راسلنا مباشرة على واتساب.</p>
  </div>
</section>

<section style="padding-top:10px;">
  <div class="wrap" style="max-width:880px;">
      <details class="faq-item">
        <summary>ما هي خدمات ناري ستور بالضبط؟</summary>
        <p>نوفّر ثلاث مجموعات: شحن الألعاب (جواهر فري فاير، شدات ببجي UC، نقاط كول أوف ديوتي CP، كوينز تيك توك)، والبطاقات والاشتراكات (آيتونز، جوجل بلاي، شاهد VIP، نتفليكس)، وخدمات نمو السوشيال ميديا (متابعين ولايكات انستقرام، متابعين تيك توك، مشاهدات يوتيوب) — بإجمالي 12 خدمة و49 فئة سعرية.</p>
      </details>
      <details class="faq-item">
        <summary>كيف أدفع؟ وهل هناك طرق دفع غير شام كاش؟</summary>
        <p>الدفع حالياً عبر شام كاش فقط، لأنه الأسرع والأكثر انتشاراً داخل سوريا. نرسل لك تفاصيل التحويل على واتساب، وترسل لنا صورة الإيصال، ثم نبدأ التنفيذ مباشرة.</p>
      </details>
      <details class="faq-item">
        <summary>كم يستغرق تنفيذ الطلب؟</summary>
        <p>شحن الألعاب والبطاقات غالباً خلال دقائق من تأكيد الدفع. الاشتراكات تحتاج وقتاً قصيراً إضافياً حسب توفر الحسابات. باقات نمو السوشيال ميديا تبدأ بالتسليم التدريجي خلال وقت قصير وتكتمل حسب حجم الباقة.</p>
      </details>
      <details class="faq-item">
        <summary>هل تطلبون كلمة مرور حسابي؟</summary>
        <p>لا، إطلاقاً. شحن الألعاب يتم عبر معرّف اللاعب (ID) فقط، وخدمات النمو عبر اسم المستخدم العام أو رابط المنشور. أي جهة تطلب كلمة مرورك باسمنا لا تمثّلنا.</p>
      </details>
      <details class="faq-item">
        <summary>هل الأسعار المعروضة نهائية؟</summary>
        <p>الأسعار المعروضة استرشادية وتتغيّر مع سعر الصرف. نؤكد لك السعر النهائي على واتساب قبل أي تحويل، فلا توجد مفاجآت بعد الدفع.</p>
      </details>
      <details class="faq-item">
        <summary>ماذا لو حدث خطأ في الطلب؟</summary>
        <p>إن كان الخطأ من طرفنا (فئة خاطئة، خدمة غير مكتملة، كود غير صالح) نصحّح الطلب فوراً أو نعيد المبلغ الخاص بالجزء غير المنفَّذ، حسب سياسة الاسترجاع المنشورة.</p>
      </details>
      <details class="faq-item">
        <summary>هل يمكنني الطلب من خارج سوريا؟</summary>
        <p>نعم، طالما يمكنك الدفع عبر شام كاش. راسلنا على واتساب وسنوضح لك الخيارات المتاحة لحالتك.</p>
      </details>
      <details class="faq-item">
        <summary>هل خدمات زيادة المتابعين آمنة على حسابي؟</summary>
        <p>نعتمد تسليماً تدريجياً يحاكي النمو الطبيعي، ولا نطلب أي بيانات دخول. مع ذلك، ننصح دائماً بإبقاء الحساب عاماً أثناء التنفيذ لضمان أفضل نتيجة.</p>
      </details>
      <details class="faq-item">
        <summary>هل يمكنني إلغاء الطلب بعد الدفع؟</summary>
        <p>قبل بدء التنفيذ يمكننا النظر في طلب الإلغاء حسب حالة العملية. بعد التنفيذ الناجح لا يمكن الاسترجاع لأن الخدمات الرقمية تُسلَّم فوراً — التفاصيل في صفحة سياسة الاسترجاع.</p>
      </details>
      <details class="faq-item">
        <summary>هل تقدّمون خصومات للطلبات الكبيرة؟</summary>
        <p>نعم، الفئات الكبيرة تحمل أصلاً سعراً أفضل لكل وحدة، ويمكن التفاوض على الطلبات المتكررة أو الكميات الكبيرة عبر واتساب.</p>
      </details>
      <details class="faq-item">
        <summary>هل أحتاج إنشاء حساب في الموقع؟</summary>
        <p>لا. لا يوجد تسجيل ولا حسابات — تختار الفئة وتراسلنا على واتساب مباشرة، وهذا يجعل العملية أسرع ويقلل البيانات التي نجمعها عنك.</p>
      </details>
      <details class="faq-item">
        <summary>كيف أتأكد أنكم لستم محتالين؟</summary>
        <p>نعرض أسعارنا علناً، ونؤكد كل التفاصيل قبل الدفع، وننشر سياسات واضحة للخصوصية والاسترجاع، ولا نطلب كلمة مرور أي حساب. يمكنك أيضاً البدء بطلب صغير لتجربة الخدمة قبل طلب فئة كبيرة.</p>
      </details>
      <details class="faq-item">
        <summary>هل الأسعار تشمل أي رسوم إضافية؟</summary>
        <p>السعر الذي نؤكده لك على واتساب هو المبلغ النهائي المطلوب تحويله. لا نضيف أي رسوم بعد ذلك.</p>
      </details>
      <details class="faq-item">
        <summary>ماذا لو تأخر تنفيذ طلبي؟</summary>
        <p>راسلنا في نفس المحادثة وسنخبرك بحالة الطلب بدقة. التأخير غالباً يكون بسبب ضغط الطلبات أو مشكلة مؤقتة من مزود الخدمة، ونبقيك على اطلاع حتى الاكتمال.</p>
      </details>
  </div>
</section>

<section class="cta-band">
  <div class="wrap">
    <h2>سؤالك غير موجود هنا؟</h2>
    <p>اسألنا مباشرة وسنجيبك خلال دقائق.</p>
    <a class="btn btn-ghost btn-lg" data-wa="مرحباً، لدي سؤال غير موجود في صفحة الأسئلة" href="#"><svg class="icon" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 3a9 9 0 00-7.8 13.5L3 21l4.6-1.2A9 9 0 1012 3z"/><path d="M8.6 8.6c-.3.9 0 2.2 1.5 3.7 1.5 1.5 2.9 1.9 3.8 1.6.5-.1.9-.6 1-1l.1-.5-1.7-1-.5.6c-.2.3-.5.3-.9.1-.6-.3-1.2-.9-1.6-1.5-.2-.4-.2-.7.1-.9l.5-.5-1-1.7-.3.1z"/></svg> اسأل الآن</a>
  </div>
</section>',
