    'crumbs_html' => '<a href="index.html">الرئيسية</a> ← <a href="guides.html">شروحات</a> ← <span>دليل نمو</span>',
    'content_html' => '<section class="hero" style="padding-bottom:36px;">
  <div class="wrap hero-grid">
    <div>
      <p class="eyebrow">دليل نمو</p>
      <h1>كيف تزيد <em>متابعين انستقرام</em> بأمان؟</h1>
      <p class="lead">دليل عملي لزيادة متابعين انستقرام بشكل آمن: كيف يعمل التسليم التدريجي، ما الذي يجب تجنّبه، وكيف تحافظ على تفاعل حسابك.</p>
    </div>
    <div class="hero-art"><img src="assets/art/svc-instagram-followers.svg" alt="كيف تزيد متابعين انستقرام بأمان؟ دليل عملي" width="480" height="320"></div>
  </div>
</section>

<div class="legal">

  <p>زيادة المتابعين ليست هدفاً بحد ذاتها — الهدف أن يبدو حسابك موثوقاً أمام الزائر الجديد فيقرر متابعتك أو الشراء منك. في هذا الدليل نشرح كيف تتم العملية بأمان وما الذي يجب تجنّبه.</p>

  <h2>كيف يعمل التسليم التدريجي؟</h2>
  <p>بدلاً من وصول آلاف المتابعين دفعة واحدة (وهو أمر يبدو غير طبيعي تماماً)، نوزّع التسليم على فترة زمنية بحيث يحاكي النمو الطبيعي للحساب. هذا يقلّل احتمال ملاحظة المنصة لأي نشاط غير معتاد، ويجعل الرقم أكثر مصداقية أمام زوار حسابك.</p>

  <h2>ما الذي نحتاجه منك؟</h2>
  <ul>
    <li>اسم المستخدم العام فقط (Username) — وليس كلمة المرور.</li>
    <li>أن يكون الحساب عاماً (Public) أثناء فترة التنفيذ.</li>
    <li>تحديد الباقة المناسبة من <a href="instagram-followers.html">صفحة الخدمة</a>.</li>
  </ul>

  <div class="note">
    <p><svg class="icon" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="5" y="11" width="14" height="9" rx="2"/><path d="M8 11V8a4 4 0 018 0v3"/></svg> <strong>لن نطلب كلمة مرورك أبداً.</strong> أي خدمة تطلب بيانات دخولك تعرّض حسابك لخطر السرقة الكامل — ارفض ذلك دائماً، حتى لو ادّعت أنها منّا.</p>
  </div>

  <h2>اختر الباقة حسب هدفك</h2>
  <ul>
    <li><a href="instagram-followers-100.html">١٠٠ متابع</a> — لتجربة الخدمة أو لحساب جديد تماماً.</li>
    <li><a href="instagram-followers-500.html">٥٠٠ متابع</a> — الأكثر طلباً، دفعة ملحوظة بسعر معقول.</li>
    <li><a href="instagram-followers-1000.html">١٠٠٠ متابع</a> — للحسابات النشطة والصفحات.</li>
    <li><a href="instagram-followers-5000.html">٥٠٠٠ متابع</a> — للحسابات التجارية وصنّاع المحتوى.</li>
  </ul>

  <h2>نصائح تجعل النتيجة أفضل</h2>
  <ol>
    <li><strong>حسّن حسابك أولاً.</strong> صورة واضحة، نبذة مفهومة، ومنشورات منظمة — وإلا لن يتحول المتابع الجديد إلى عميل.</li>
    <li><strong>انشر بانتظام أثناء فترة التسليم.</strong> الحساب النشط يبدو طبيعياً أكثر.</li>
    <li><strong>لا تجمع عدة خدمات في نفس اليوم.</strong> وزّع الطلبات على فترات.</li>
    <li><strong>اهتم بالتفاعل لا بالرقم فقط.</strong> فكّر أيضاً في <a href="instagram-likes.html">باقات اللايكات</a> لتعزيز ظهور منشوراتك.</li>
  </ol>

  <h2>ما الذي لا نعد به</h2>
  <p>نحن صادقون معك: لا أحد يستطيع ضمان أن يتحول المتابعون إلى مشترين، ولا أن يبقى الرقم ثابتاً للأبد على أي منصة. ما نضمنه هو تنفيذ الباقة المتفق عليها بتسليم تدريجي وآمن، ومتابعتك حتى اكتمالها.</p>

  <div class="note" style="margin-top:34px;">
    <p><svg class="icon" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 3a9 9 0 00-7.8 13.5L3 21l4.6-1.2A9 9 0 1012 3z"/><path d="M8.6 8.6c-.3.9 0 2.2 1.5 3.7 1.5 1.5 2.9 1.9 3.8 1.6.5-.1.9-.6 1-1l.1-.5-1.7-1-.5.6c-.2.3-.5.3-.9.1-.6-.3-1.2-.9-1.6-1.5-.2-.4-.2-.7.1-.9l.5-.5-1-1.7-.3.1z"/></svg> <strong>جاهز للطلب؟</strong> راسلنا على واتساب وسنساعدك خطوة بخطوة حتى إتمام طلبك.</p>
    <p style="margin-top:12px;"><a class="btn btn-whatsapp" data-wa="مرحباً، قرأت الدليل وأرغب بالطلب" href="#"><svg class="icon" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 3a9 9 0 00-7.8 13.5L3 21l4.6-1.2A9 9 0 1012 3z"/><path d="M8.6 8.6c-.3.9 0 2.2 1.5 3.7 1.5 1.5 2.9 1.9 3.8 1.6.5-.1.9-.6 1-1l.1-.5-1.7-1-.5.6c-.2.3-.5.3-.9.1-.6-.3-1.2-.9-1.6-1.5-.2-.4-.2-.7.1-.9l.5-.5-1-1.7-.3.1z"/></svg> تواصل الآن</a></p>
