    'crumbs_html' => '<a href="index.html">الرئيسية</a> ← <a href="guides.html">شروحات</a> ← <span>دليل الدفع</span>',
    'content_html' => '<section class="hero" style="padding-bottom:36px;">
  <div class="wrap hero-grid">
    <div>
      <p class="eyebrow">دليل الدفع</p>
      <h1>كيف تدفع عبر <em>شام كاش</em>؟ الدليل الكامل</h1>
      <p class="lead">شرح كامل لطريقة الدفع عبر شام كاش عند الشراء من ناري ستور: خطوات التحويل، ما الذي ترسله لنا، وكيف نؤكد استلام المبلغ.</p>
    </div>
    <div class="hero-art"><img src="assets/art/payment-shamcash.svg" alt="كيف تدفع عبر شام كاش؟ دليل خطوة بخطوة" width="480" height="320"></div>
  </div>
</section>

<div class="legal">

  <p>شام كاش هو وسيلة الدفع المعتمدة في ناري ستور، وقد اخترناه لأنه الأسرع والأوسع انتشاراً داخل سوريا، ولأنه لا يتطلب منك أي بطاقة بنكية أو حساب دولي. في هذا الدليل نشرح لك العملية كاملة من البداية حتى استلام خدمتك.</p>

  <h2>قبل أن تبدأ</h2>
  <ul>
    <li>حدّد الخدمة والفئة التي تريدها من <a href="price-list.html">قائمة الأسعار</a>.</li>
    <li>تأكد أن رصيد محفظتك في شام كاش يغطي قيمة الطلب.</li>
    <li>جهّز البيانات المطلوبة (معرّف اللاعب أو اسم المستخدم أو البريد الإلكتروني حسب الخدمة).</li>
  </ul>

  <h2>الخطوات بالترتيب</h2>
  <ol>
    <li><strong>اختر الفئة واضغط زر الطلب.</strong> ستفتح محادثة واتساب جاهزة تحتوي اسم المنتج وسعره المعروض.</li>
    <li><strong>انتظر تأكيد السعر النهائي.</strong> الأسعار المعروضة استرشادية وتتغير مع سعر الصرف، لذلك نؤكد لك السعر الفعلي قبل أي تحويل.</li>
    <li><strong>استلم تفاصيل التحويل.</strong> نرسل لك رقم الحساب أو المحفظة المطلوبة على شام كاش.</li>
    <li><strong>نفّذ التحويل من تطبيق شام كاش.</strong> أدخل الرقم والمبلغ بدقة، وتأكد من المبلغ قبل الإرسال.</li>
    <li><strong>أرسل لنا صورة الإيصال.</strong> هذه أهم خطوة لتسريع التنفيذ، لأنها تثبت العملية فوراً.</li>
    <li><strong>استلم خدمتك.</strong> نبدأ التنفيذ مباشرة بعد التحقق، ونعلمك فور اكتماله.</li>
  </ol>

  <div class="note">
    <p><svg class="icon" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 3l7 3v6c0 5-3.5 7.5-7 9-3.5-1.5-7-4-7-9V6l7-3z"/></svg> <strong>ملاحظة أمان:</strong> لا نطلب منك أبداً كلمة مرور أي حساب، ولا رمز تحقق (OTP) يصلك على هاتفك، ولا بيانات بطاقتك البنكية. أي رسالة تطلب ذلك باسمنا ليست منّا.</p>
  </div>

  <h2>أخطاء شائعة يجب تجنّبها</h2>
  <ul>
    <li>التحويل قبل تأكيد السعر النهائي معنا — قد يختلف السعر عن المعروض.</li>
    <li>إرسال المبلغ لرقم غير الرقم الذي أرسلناه لك في نفس المحادثة.</li>
    <li>عدم إرسال صورة الإيصال، ما يؤخر التحقق والتنفيذ.</li>
    <li>كتابة معرّف اللاعب أو اسم المستخدم بشكل خاطئ — راجعه مرتين قبل الإرسال.</li>
  </ul>

  <h2>كم يستغرق التحقق من الدفع؟</h2>
  <p>في الأوقات العادية نتحقق من الإيصال خلال دقائق قليلة، ثم يبدأ التنفيذ مباشرة. في أوقات الذروة قد يستغرق التحقق وقتاً أطول قليلاً، لكننا نبقيك على اطلاع بحالة طلبك في نفس المحادثة.</p>

  <h2>ماذا لو دفعت وحدث خطأ؟</h2>
  <p>راسلنا فوراً في نفس المحادثة مع صورة الإيصال. إن كان الخطأ من طرفنا نصحّح الطلب أو نعيد المبلغ المتعلق بالجزء غير المنفَّذ، وفق <a href="refund-policy.html">سياسة الاسترجاع</a> المنشورة.</p>

  <div class="note" style="margin-top:34px;">
    <p><svg class="icon" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 3a9 9 0 00-7.8 13.5L3 21l4.6-1.2A9 9 0 1012 3z"/><path d="M8.6 8.6c-.3.9 0 2.2 1.5 3.7 1.5 1.5 2.9 1.9 3.8 1.6.5-.1.9-.6 1-1l.1-.5-1.7-1-.5.6c-.2.3-.5.3-.9.1-.6-.3-1.2-.9-1.6-1.5-.2-.4-.2-.7.1-.9l.5-.5-1-1.7-.3.1z"/></svg> <strong>جاهز للطلب؟</strong> راسلنا على واتساب وسنساعدك خطوة بخطوة حتى إتمام طلبك.</p>
    <p style="margin-top:12px;"><a class="btn btn-whatsapp" data-wa="مرحباً، قرأت الدليل وأرغب بالطلب" href="#"><svg class="icon" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 3a9 9 0 00-7.8 13.5L3 21l4.6-1.2A9 9 0 1012 3z"/><path d="M8.6 8.6c-.3.9 0 2.2 1.5 3.7 1.5 1.5 2.9 1.9 3.8 1.6.5-.1.9-.6 1-1l.1-.5-1.7-1-.5.6c-.2.3-.5.3-.9.1-.6-.3-1.2-.9-1.6-1.5-.2-.4-.2-.7.1-.9l.5-.5-1-1.7-.3.1z"/></svg> تواصل الآن</a></p>
  </div>
</div>

<section class="cta-band">
