    'crumbs_html' => '<a href="index.html">الرئيسية</a> ← <a href="guides.html">شروحات</a> ← <span>دليل شحن</span>',
    'content_html' => '<section class="hero" style="padding-bottom:36px;">
  <div class="wrap hero-grid">
    <div>
      <p class="eyebrow">دليل شحن</p>
      <h1>كيف تشحن <em>جواهر فري فاير</em> بأمان؟</h1>
      <p class="lead">دليل مفصّل لشحن جواهر فري فاير: كيف تجد معرّف اللاعب، كيف تختار الفئة المناسبة، وكيف تتم عملية الشحن عبر شام كاش خطوة بخطوة.</p>
    </div>
    <div class="hero-art"><img src="assets/art/svc-freefire.svg" alt="كيف تشحن جواهر فري فاير عبر شام كاش؟ شرح كامل" width="480" height="320"></div>
  </div>
</section>

<div class="legal">

  <p>شحن جواهر فري فاير عملية بسيطة إذا عرفت الخطوات الصحيحة. المهم أن تعرف معرّف اللاعب الخاص بك، وأن تختار الفئة المناسبة، وألا تشارك بيانات حسابك مع أي جهة.</p>

  <h2>أولاً: كيف تجد معرّف اللاعب (ID)؟</h2>
  <ol>
    <li>افتح لعبة فري فاير على جهازك.</li>
    <li>اضغط على صورة الحساب الشخصي في أعلى الشاشة.</li>
    <li>ستجد رقم المعرّف (Player ID) مكتوباً أسفل اسمك مباشرة.</li>
    <li>انسخ الرقم كما هو تماماً بدون مسافات أو رموز إضافية.</li>
  </ol>

  <div class="note">
    <p><svg class="icon" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M8 12l3 3 5-6"/></svg> تأكد من نسخ الرقم بدقة. أي رقم خاطئ يعني وصول الشحن لحساب شخص آخر، ولا يمكن التراجع بعد التنفيذ.</p>
  </div>

  <h2>ثانياً: اختر الفئة المناسبة</h2>
  <p>الفئات الصغيرة مناسبة للتجربة أو لشراء عنصر محدد بسرعة، بينما الفئات الكبيرة تعطيك سعراً أفضل لكل جوهرة. راجع <a href="freefire-topup.html">صفحة شحن فري فاير</a> لعرض كل الفئات بأسعارها المعلنة.</p>
  <ul>
    <li><a href="freefire-100-diamonds.html">١٠٠ جوهرة</a> — للتجربة أو الشراء السريع.</li>
    <li><a href="freefire-310-diamonds.html">٣١٠ جوهرة</a> — الأكثر طلباً وتوازناً.</li>
    <li><a href="freefire-520-diamonds.html">٥٢٠ جوهرة</a> — خيار موفّر للاعب المنتظم.</li>
    <li><a href="freefire-1080-diamonds.html">١٠٨٠ جوهرة</a> — للاعبين الجادين.</li>
    <li><a href="freefire-2200-diamonds.html">٢٢٠٠ جوهرة</a> — أفضل سعر لكل جوهرة.</li>
  </ul>

  <h2>ثالثاً: أتمم الطلب</h2>
  <ol>
    <li>اضغط زر الطلب في صفحة الفئة، فتفتح محادثة واتساب جاهزة.</li>
    <li>أرسل لنا معرّف اللاعب، وسنؤكد لك اسم الحساب للتأكد أنه الصحيح.</li>
    <li>حوّل المبلغ عبر شام كاش وأرسل صورة الإيصال — راجع <a href="how-to-pay-sham-cash.html">دليل الدفع</a>.</li>
    <li>استلم الجواهر في حسابك خلال دقائق، وتحقق منها داخل اللعبة.</li>
  </ol>

  <h2>أسئلة يسألها اللاعبون كثيراً</h2>
  <h3>هل أحتاج كلمة مرور حسابي؟</h3>
  <p>لا إطلاقاً. الشحن يتم عبر معرّف اللاعب فقط. أي جهة تطلب كلمة مرورك تحاول سرقة حسابك.</p>
  <h3>هل يمكن الشحن لحساب صديق؟</h3>
  <p>نعم، فقط أرسل معرّف حسابه بدلاً من حسابك، وسنؤكد لك الاسم قبل التنفيذ.</p>
  <h3>ماذا لو لم تصل الجواهر؟</h3>
  <p>راسلنا في نفس المحادثة فوراً. نتحقق من العملية ونصحّحها، وإن كان الخطأ من طرفنا نلتزم بتصحيحه أو إعادة المبلغ.</p>

  <div class="note" style="margin-top:34px;">
    <p><svg class="icon" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 3a9 9 0 00-7.8 13.5L3 21l4.6-1.2A9 9 0 1012 3z"/><path d="M8.6 8.6c-.3.9 0 2.2 1.5 3.7 1.5 1.5 2.9 1.9 3.8 1.6.5-.1.9-.6 1-1l.1-.5-1.7-1-.5.6c-.2.3-.5.3-.9.1-.6-.3-1.2-.9-1.6-1.5-.2-.4-.2-.7.1-.9l.5-.5-1-1.7-.3.1z"/></svg> <strong>جاهز للطلب؟</strong> راسلنا على واتساب وسنساعدك خطوة بخطوة حتى إتمام طلبك.</p>
