    'crumbs_html' => '<a href="index.html">الرئيسية</a> ← <a href="guides.html">شروحات</a> ← <span>دليل شحن</span>',
    'content_html' => '<section class="hero" style="padding-bottom:36px;">
  <div class="wrap hero-grid">
    <div>
      <p class="eyebrow">دليل شحن</p>
      <h1>كيف تشحن <em>شدات ببجي UC</em> خطوة بخطوة؟</h1>
      <p class="lead">شرح طريقة شحن شدات ببجي موبايل UC عبر شام كاش: إيجاد معرّف الحساب، اختيار الفئة، وأشهر الأخطاء التي يجب تجنّبها.</p>
    </div>
    <div class="hero-art"><img src="assets/art/svc-pubg.svg" alt="كيف تشحن شدات ببجي موبايل UC؟ دليل المبتدئين" width="480" height="320"></div>
  </div>
</section>

<div class="legal">

  <p>شحن شدات ببجي موبايل (UC) لا يحتاج أي بيانات حساسة — فقط معرّف الحساب داخل اللعبة. في هذا الدليل نشرح لك الطريقة كاملة وأشهر الأخطاء التي تسبب مشاكل.</p>

  <h2>أولاً: أين تجد معرّف الحساب؟</h2>
  <ol>
    <li>افتح لعبة ببجي موبايل.</li>
    <li>اضغط على أيقونة الملف الشخصي (Profile) في يمين الشاشة.</li>
    <li>ستجد رقم المعرّف أسفل اسم اللاعب مباشرة.</li>
    <li>انسخ الرقم بالكامل بدون أي مسافات.</li>
  </ol>

  <h2>ثانياً: اختر فئة UC المناسبة</h2>
  <p>راجع <a href="pubg-mobile-uc-topup.html">صفحة شحن ببجي</a> لعرض كل الفئات بأسعارها. الفئات الأكبر تعطي سعراً أفضل لكل وحدة UC:</p>
  <ul>
    <li><a href="pubg-60-uc.html">٦٠ UC</a> — للتجربة أو شراء عنصر صغير.</li>
    <li><a href="pubg-325-uc.html">٣٢٥ UC</a> — الأكثر طلباً بين اللاعبين.</li>
    <li><a href="pubg-660-uc.html">٦٦٠ UC</a> — مناسبة للاعب المنتظم.</li>
    <li><a href="pubg-1800-uc.html">١٨٠٠ UC</a> — للاعبين الجادين وصنّاع المحتوى.</li>
    <li><a href="pubg-3850-uc.html">٣٨٥٠ UC</a> — أفضل قيمة لكل وحدة.</li>
  </ul>

  <div class="note">
    <p><svg class="icon" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M13 2 4 14h6l-1 8 9-12h-6l1-8z"/></svg> <strong>نصيحة:</strong> إن كنت تخطط لشراء الباس الموسمي وعناصر إضافية، فالفئات الكبيرة توفّر عليك أكثر من شراء عدة فئات صغيرة متتالية.</p>
  </div>

  <h2>ثالثاً: أتمم الطلب</h2>
  <ol>
    <li>اضغط زر الطلب في صفحة الفئة لتفتح محادثة واتساب جاهزة.</li>
    <li>أرسل معرّف الحساب، وسنؤكد لك اسم اللاعب للتحقق.</li>
    <li>حوّل عبر شام كاش وأرسل صورة الإيصال.</li>
    <li>استلم الشدات في حسابك خلال دقائق.</li>
  </ol>

  <h2>أخطاء شائعة تسبب تأخير الشحن</h2>
  <ul>
    <li>إرسال اسم اللاعب بدل رقم المعرّف — نحتاج الرقم تحديداً.</li>
    <li>خطأ في رقم واحد من المعرّف، ما يؤدي لشحن حساب آخر.</li>
    <li>الدفع قبل تأكيد السعر النهائي.</li>
    <li>عدم إرسال إيصال التحويل، ما يؤخّر التحقق.</li>
  </ul>

  <div class="note" style="margin-top:34px;">
    <p><svg class="icon" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 3a9 9 0 00-7.8 13.5L3 21l4.6-1.2A9 9 0 1012 3z"/><path d="M8.6 8.6c-.3.9 0 2.2 1.5 3.7 1.5 1.5 2.9 1.9 3.8 1.6.5-.1.9-.6 1-1l.1-.5-1.7-1-.5.6c-.2.3-.5.3-.9.1-.6-.3-1.2-.9-1.6-1.5-.2-.4-.2-.7.1-.9l.5-.5-1-1.7-.3.1z"/></svg> <strong>جاهز للطلب؟</strong> راسلنا على واتساب وسنساعدك خطوة بخطوة حتى إتمام طلبك.</p>
    <p style="margin-top:12px;"><a class="btn btn-whatsapp" data-wa="مرحباً، قرأت الدليل وأرغب بالطلب" href="#"><svg class="icon" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 3a9 9 0 00-7.8 13.5L3 21l4.6-1.2A9 9 0 1012 3z"/><path d="M8.6 8.6c-.3.9 0 2.2 1.5 3.7 1.5 1.5 2.9 1.9 3.8 1.6.5-.1.9-.6 1-1l.1-.5-1.7-1-.5.6c-.2.3-.5.3-.9.1-.6-.3-1.2-.9-1.6-1.5-.2-.4-.2-.7.1-.9l.5-.5-1-1.7-.3.1z"/></svg> تواصل الآن</a></p>
  </div>
</div>

