<section id="faq">
  <div class="wrap">
    <div class="section-head center">
      <p class="eyebrow">الأسئلة الشائعة</p>
      <h2>كل ما تحتاج معرفته قبل الطلب</h2>
    </div>
    <div style="max-width:860px;margin-inline:auto;">
      <details class="faq-item">
        <summary>ما هي خدمات ناري ستور بالضبط؟</summary>
        <p>نوفّر ثلاث مجموعات: شحن الألعاب (جواهر فري فاير، شدات ببجي UC، نقاط كول أوف ديوتي CP، كوينز تيك توك)، والبطاقات والاشتراكات (آيتونز، جوجل بلاي، شاهد VIP، نتفليكس)، وخدمات نمو السوشيال ميديا (متابعين ولايكات انستقرام، متابعين تيك توك، مشاهدات يوتيوب) — بإجمالي 12 خدمة و49 فئة سعرية.</p>
      </details>
      <details class="faq-item">
        <summary>كيف أدفع؟ وهل هناك طرق دفع غير شام كاش؟</summary>
        <p>الدفع حالياً عبر شام كاش فقط، لأنه الأسرع والأكثر انتشاراً داخل سوريا. نرسل لك تفاصيل التحويل على واتساب، وترسل لنا صورة الإيصال، ثم نبدأ التنفيذ مباشرة.</p>
      </details>
      <details class="faq-item">
        <summary>كم يستغرق تنفيذ الطلب؟</summary>
        <p>شحن الألعاب والبطاقات غالباً خلال دقائق من تأكيد الدفع. الاشتراكات تحتاج وقتاً قصيراً إضافياً حسب توفر الحسابات. باقات نمو السوشيال ميديا تبدأ بالتسليم التدريجي خلال وقت قصير وتكتمل حسب حجم الباقة.</p>
      </details>
      <details class="faq-item">
        <summary>هل تطلبون كلمة مرور حسابي؟</summary>
        <p>لا، إطلاقاً. شحن الألعاب يتم عبر معرّف اللاعب (ID) فقط، وخدمات النمو عبر اسم المستخدم العام أو رابط المنشور. أي جهة تطلب كلمة مرورك باسمنا لا تمثّلنا.</p>
      </details>
      <details class="faq-item">
        <summary>هل الأسعار المعروضة نهائية؟</summary>
        <p>الأسعار المعروضة استرشادية وتتغيّر مع سعر الصرف. نؤكد لك السعر النهائي على واتساب قبل أي تحويل، فلا توجد مفاجآت بعد الدفع.</p>
      </details>
      <details class="faq-item">
        <summary>ماذا لو حدث خطأ في الطلب؟</summary>
        <p>إن كان الخطأ من طرفنا (فئة خاطئة، خدمة غير مكتملة، كود غير صالح) نصحّح الطلب فوراً أو نعيد المبلغ الخاص بالجزء غير المنفَّذ، حسب سياسة الاسترجاع المنشورة.</p>
      </details>
      <details class="faq-item">
        <summary>هل يمكنني الطلب من خارج سوريا؟</summary>
        <p>نعم، طالما يمكنك الدفع عبر شام كاش. راسلنا على واتساب وسنوضح لك الخيارات المتاحة لحالتك.</p>
      </details>
      <details class="faq-item">
        <summary>هل خدمات زيادة المتابعين آمنة على حسابي؟</summary>
        <p>نعتمد تسليماً تدريجياً يحاكي النمو الطبيعي، ولا نطلب أي بيانات دخول. مع ذلك، ننصح دائماً بإبقاء الحساب عاماً أثناء التنفيذ لضمان أفضل نتيجة.</p>
      </details>
    </div>
    <p style="text-align:center; margin-top:28px;">
      <a class="btn btn-ghost" href="faq.html">صفحة الأسئلة الكاملة <svg class="icon" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><line x1="19" y1="12" x2="5" y2="12"/><polyline points="11,6 5,12 11,18"/></svg></a>
    </p>
  </div>
</section>

