    'content_html' => '<div class="legal">
  <h1>سياسة الخصوصية</h1>
  <p class="updated"><svg class="icon" width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="9"/><line x1="12" y1="7" x2="12" y2="12"/><line x1="12" y1="12" x2="16" y2="14"/></svg> آخر تحديث: سبتمبر 2026</p>

  <p>نحرص في ناري ستور على احترام خصوصية زوارنا وعملائنا عبر جميع خدماتنا. توضح هذه الصفحة نوع المعلومات التي نجمعها، وكيف نستخدمها، وما الذي لا نطلبه منك أبداً.</p>

  <h2>المعلومات التي نجمعها</h2>
  <ul>
    <li>معلومات ترسلها لنا طواعية عبر واتساب: الاسم، معرّف اللاعب أو اسم المستخدم، والبريد الإلكتروني اللازم لتفعيل بعض الاشتراكات.</li>
    <li>تفاصيل الطلب والدفع اللازمة لتنفيذ الخدمة المطلوبة (مثل صورة إيصال التحويل).</li>
    <li>بيانات تصفح عامة وغير شخصية قد يجمعها المتصفح أو مزوّد الاستضافة تلقائياً.</li>
  </ul>

  <h2>ما لا نطلبه أبداً</h2>
  <div class="note">
    <p>لا نطلب في أي وقت كلمة مرور أي حساب لعبة أو منصة تواصل اجتماعي أو منصة بث، ولا رموز التحقق (OTP)، ولا بيانات بطاقتك البنكية. أي جهة تطلب ذلك باسمنا لا تمثّلنا.</p>
  </div>

  <h2>كيف نستخدم هذه المعلومات</h2>
  <ul>
    <li>لتنفيذ طلبك (شحن، تفعيل بطاقة أو اشتراك، أو باقة نمو).</li>
    <li>للتواصل معك بخصوص حالة الطلب أو الاستفسارات.</li>
    <li>لتحسين جودة الخدمة المقدمة عبر الموقع.</li>
  </ul>

  <h2>مشاركة البيانات</h2>
  <p>لا نبيع بياناتك ولا نشاركها مع أي طرف ثالث لأغراض تسويقية. تُستخدم المعلومات فقط لغرض تنفيذ طلبك والتواصل معك بشأنه.</p>

  <h2>ملفات تعريف الارتباط والتخزين المحلي</h2>
  <p>يستخدم الموقع تخزيناً محلياً بسيطاً في متصفحك لأغراض تقنية فقط (مثل تذكّر إغلاقك لشريط الإعلان، أو عدد أسئلتك للمساعد الذكي خلال الجلسة). لا نستخدم تتبعاً إعلانياً.</p>

  <h2>المساعد الذكي</h2>
  <p>إذا كان المساعد الذكي مفعّلاً، فإن نص سؤالك يُرسَل من متصفحك إلى مزوّد الذكاء الاصطناعي (OpenRouter) للحصول على إجابة. لا ترسل عبر المساعد أي معلومات حساسة أو بيانات دخول.</p>

  <h2>حقوقك</h2>
  <p>يمكنك في أي وقت طلب حذف بياناتك التي أرسلتها لنا عبر واتساب. راسلنا على الرقم <span data-wa-display>+963 994 898 623</span> وسننفّذ الطلب.</p>

</div>',
