    'crumbs_html' => '<a href="index.html">الرئيسية</a> ← <span>سياسة الاسترجاع والإلغاء</span>',
    'content_html' => '<div class="legal">
  <h1>سياسة الاسترجاع والإلغاء</h1>
  <p class="updated"><svg class="icon" width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="9"/><line x1="12" y1="7" x2="12" y2="12"/><line x1="12" y1="12" x2="16" y2="14"/></svg> آخر تحديث: سبتمبر 2026</p>

  <p>نحرص على وضوح تام بخصوص إمكانية إلغاء أو استرجاع الطلبات. اقرأ هذه السياسة قبل تأكيد أي طلب.</p>

  <h2>قبل تأكيد الدفع</h2>
  <p>يمكنك إلغاء الطلب أو تعديله بحرية كاملة طالما لم تحوّل المبلغ بعد. نؤكد كل التفاصيل معك قبل أي تحويل تحديداً لتفادي أي التباس.</p>

  <h2>بعد الدفع وقبل بدء التنفيذ</h2>
  <p>إن حوّلت المبلغ ولم نكن قد بدأنا التنفيذ، راسلنا فوراً في نفس المحادثة. سننظر في طلب الإلغاء حسب حالة العملية، وغالباً يمكن الاسترجاع في هذه المرحلة.</p>

  <h2>بعد التنفيذ الناجح</h2>
  <p>لا يمكن استرجاع قيمة أي طلب نُفِّذ بنجاح (شحن وصل للحساب، كود بطاقة أُرسِل، أو باقة نمو بدأ تسليمها)، وذلك لطبيعة الخدمات الرقمية غير القابلة للإرجاع بعد التسليم.</p>

  <h2>حالات نتحمّل فيها المسؤولية كاملة</h2>
  <ul>
    <li>شحن فئة أو باقة مختلفة عن المطلوبة والمتفق عليها.</li>
    <li>عدم اكتمال تنفيذ الخدمة المدفوعة.</li>
    <li>إرسال كود بطاقة غير صالح للاستخدام.</li>
    <li>عدم تفعيل اشتراك بعد الدفع.</li>
  </ul>
  <div class="note">
    <p>في كل هذه الحالات نلتزم بتصحيح الطلب فوراً أو إعادة المبلغ الخاص بالجزء غير المنفَّذ، بعد التحقق من المشكلة.</p>
  </div>

  <h2>حالات خارجة عن مسؤوليتنا</h2>
  <ul>
    <li>إرسالك معرّف لاعب أو اسم مستخدم خاطئ أدى لوصول الخدمة لحساب آخر.</li>
    <li>إجراء تتخذه المنصة بحق حسابك لأسباب تتعلق بمخالفتك لشروطها.</li>
    <li>تأخير أو عطل من مزوّد اللعبة أو المنصة أو نظام الدفع نفسه — نتابع معك حتى الحل لكن لا نتحمل مسؤولية العطل ذاته.</li>
  </ul>

  <h2>كيف تقدّم طلب استرجاع</h2>
  <p>راسلنا على واتساب <span data-wa-display>+963 994 898 623</span> مع تفاصيل الطلب وسبب الاسترجاع وصورة الإيصال، وسنرد عليك بأسرع وقت ممكن.</p>

</div>',
