      </div>
      <div class="review-card">
        <div class="review-stars">★★★★★</div>
        <p>"جربت باقة زيادة متابعين انستقرام لصفحتي التجارية، والتسليم كان تدريجي ومريح وما حسّيت بأي شي غريب على الحساب."</p>
        <div class="review-name"><span class="review-avatar">ر</span> ريم ع.</div>
      </div>
      <div class="review-card">
        <div class="review-stars">★★★★★</div>
        <p>"اشتركت بشاهد VIP عن طريقهم بعد ما ترددت كتير، والتفعيل كان سريع والتواصل عبر واتساب كان مريح ومباشر."</p>
        <div class="review-name"><span class="review-avatar">ع</span> عمر ك.</div>
      </div>
      <div class="review-card">
        <div class="review-stars">★★★★★</div>
        <p>"أفضل شي عندهم إنو السعر بينقال قبل الدفع وما في مفاجآت. شحنت شدات ببجي مرتين وكل مرة نفس السرعة."</p>
