    'crumbs_html' => '<a href="index.html">الرئيسية</a> ← <span>الشروط والأحكام</span>',
    'content_html' => '<div class="legal">
  <h1>الشروط والأحكام</h1>
  <p class="updated"><svg class="icon" width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="9"/><line x1="12" y1="7" x2="12" y2="12"/><line x1="12" y1="12" x2="16" y2="14"/></svg> آخر تحديث: سبتمبر 2026</p>

  <p>يُرجى قراءة هذه الشروط بعناية قبل استخدام خدمات ناري ستور. استخدامك للموقع أو التواصل معنا لطلب أي خدمة يُعدّ موافقة عليها.</p>

  <h2>طبيعة الخدمات</h2>
  <ul>
    <li>شحن الألعاب (فري فاير، ببجي موبايل، كول أوف ديوتي موبايل، كوينز تيك توك) عبر معرّف اللاعب أو اسم المستخدم.</li>
    <li>بيع بطاقات آيتونز وجوجل بلاي، وتفعيل اشتراكات شاهد VIP ونتفليكس.</li>
    <li>خدمات زيادة متابعين ولايكات ومشاهدات لحسابات التواصل الاجتماعي بتسليم تدريجي.</li>
  </ul>

  <h2>مسؤولية العميل</h2>
  <ul>
    <li>التأكد من صحة معرّف اللاعب أو اسم المستخدم أو البريد الإلكتروني قبل التنفيذ — الشحن لمعرّف خاطئ لا يمكن التراجع عنه.</li>
    <li>تأكيد التحويل عبر شام كاش وإرفاق إثبات الدفع.</li>
    <li>عدم مشاركة كلمة مرور أي حساب مع أي جهة، بما في ذلك نحن — فنحن لا نطلبها إطلاقاً.</li>
    <li>ألا يكون استخدام الخدمة مخالفاً لشروط المنصة أو اللعبة التي يستخدمها العميل.</li>
  </ul>

  <h2>التنفيذ والتوقيت</h2>
  <p>نسعى لتنفيذ معظم الطلبات خلال دقائق إلى ساعة كحد أقصى. قد يطول الوقت في حالات استثنائية خارجة عن إرادتنا مثل تأخر تأكيد الدفع أو خلل تقني من مزوّد اللعبة أو المنصة.</p>

  <h2>الأسعار</h2>
  <p>الأسعار المعروضة استرشادية وقابلة للتحديث حسب سعر الصرف وتقلبات السوق، ويتم تأكيد السعر النهائي عبر واتساب قبل إتمام أي دفع.</p>

  <h2>حدود المسؤولية</h2>
  <p>لا نتحمل مسؤولية أي إجراء تتخذه المنصة أو اللعبة بحق حساب العميل نتيجة مخالفته لشروطها. كما لا نضمن نتائج تسويقية محددة من خدمات النمو (مثل المبيعات أو التفاعل)، وإنما نلتزم بتنفيذ الباقة المتفق عليها.</p>

  <h2>إخلاء مسؤولية عن العلامات التجارية</h2>
  <p>ناري ستور متجر مستقل غير تابع رسمياً لأي من الجهات الناشرة للألعاب أو منصات التواصل الاجتماعي أو منصات البث المذكورة في الموقع. أسماء المنصات تُذكر لغرض التوضيح فقط، وكل العلامات التجارية ملك لأصحابها.</p>

  <h2>التواصل</h2>
  <p>لأي استفسار بخصوص هذه الشروط، تواصل معنا عبر واتساب على الرقم <span data-wa-display>+963 994 898 623</span>.</p>

</div>',
  ),
